def samples(knots,step=.75):
 a=np.asarray(knots); dist=np.maximum(np.linalg.norm(np.diff(a[:,:2],axis=0),axis=1),4); t=np.r_[0,np.cumsum(dist)]
 tt=np.linspace(0,t[-1],int(t[-1]/step)+1)
 xy=CubicSpline(t,a[:,:2],axis=0,bc_type='natural')(tt)
 dv=CubicSpline(t,a[:,:2],axis=0,bc_type='natural')(tt,1); dv/=np.maximum(np.linalg.norm(dv,axis=1)[:,None],1e-8)
 width=np.maximum(0,PchipInterpolator(t,a[:,2])(tt)); z=(width*MM+.3)/1.187
 O=np.maximum(0,11.15-.0967*(z-10.91)**2)/MM
 tip=xy+O[:,None]*dv
 return np.c_[tip,z]

def render(a,size=512):
 p=np.ascontiguousarray(samples(a),dtype=np.float64); im=np.zeros((size,size),np.float32)
 lib.render(p.ctypes.data,len(p),im.ctypes.data,size,size/1024)
 return im

def preview(paths,name='fit'):
 ims=[render(a,1024) for a in paths]; im=np.maximum.reduce(ims); tar=cv2.imread('/app/target.png')[:,:,0]<100
 out=np.full((1024,1024,3),255,np.uint8); out[tar]=(170,170,170); out[im>=.5]=(0,0,0); out[(im>=.5)&~tar]=(60,60,230); out[tar&(im<.5)]=(220,150,80)
 cv2.imwrite(str(D/(name+'.png')),out)
 np.savez(D/(name+'.npz'),**{f'p{i}':np.array(a) for i,a in enumerate(paths)})
 print(name,'iou',np.sum((im>=.5)&tar)/np.sum((im>=.5)|tar),flush=True)
 return ims

if __name__=='__main__':
